			; Main.bas 136: End If
if14_1:

			; Main.bas 137: Next
			dw kw_next1l_n, var_findpair_y, 5, for13_t
for13_e:

			; Main.bas 138: Next
			dw kw_next1l_n, var_findpair_x, 5, for12_t
