; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do6_t_go:			ld sp, do6_t
			jp ntc_xn
if8_e_go:			ld sp, if8_e
			jp ntc_xn
if9_e_go:			ld sp, if9_e
			jp ntc_xn
if10_e_go:			ld sp, if10_e
			jp ntc_xn
sel15_e_go:			ld sp, sel15_e
			jp ntc_xn
lbl_inner_addone_gs:			ld (lbl_inner_addone_rs), sp
			ld sp, lbl_inner_addone
			jp ntc_xn
lbl_inner_addone_rt:			ld sp, (lbl_inner_addone_rs)
			jp ntc_xn
lbl_inner_addten_gs:			ld (lbl_inner_addten_rs), sp
			ld sp, lbl_inner_addten
			jp ntc_xn
lbl_inner_addten_rt:			ld sp, (lbl_inner_addten_rs)
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld de, var_chk_got		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; want
			ldi
			ldi
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn
p_area_c:		; call area (normal)
			pop hl			; a
			ld de, var_area_a		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; b
			ldi
			ldi
			ld hl, 0
			ld (var_area_area), hl
			ld (p_area_rs), sp
			ld sp, p_area
			jp ntc_xn
p_area_r:		; end of area
			ld sp, (p_area_rs)
			jp ntc_xn
p_shout_c:		; call shout (normal)
			pop hl			; txt
			ld (p_shout_a0), hl
			ld de, var_shout_txt
			ld b, 40
p_shout_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_si0_e
			inc hl
			inc de
			djnz p_shout_si0
			xor a
			ld (de), a
p_shout_si0_e:
			ld (p_shout_rs), sp
			ld sp, p_shout
			jp ntc_xn
p_shout_r:		; end of shout
			ld de, (p_shout_a0)
			ld hl, var_shout_txt
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_shout_so0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_so0_e
			inc hl
			inc de
			djnz p_shout_so0
			xor a
			ld (de), a
p_shout_so0_e:
			ld sp, (p_shout_rs)
			jp ntc_xn
p_findpair_c:		; call findpair (normal)
			pop hl			; target
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_findpair_target), de
			ld hl, 0
			ld (var_findpair_findpair), hl
			ld (var_findpair_x), hl
			ld (var_findpair_y), hl
			ld (p_findpair_rs), sp
			ld sp, p_findpair
			jp ntc_xn
p_findpair_r:		; end of findpair
			ld sp, (p_findpair_rs)
			jp ntc_xn
p_inner_c:		; call inner (normal)
			ld hl, 0
			ld (var_inner_inner), hl
			ld (var_inner_r), hl
			ld (p_inner_rs), sp
			ld sp, p_inner
			jp ntc_xn
p_inner_r:		; end of inner
			ld sp, (p_inner_rs)
			jp ntc_xn
p_helper_c:		; call helper (normal)
			ld hl, 0
			ld (var_helper_helper), hl
			ld (p_helper_rs), sp
			ld sp, p_helper
			jp ntc_xn
p_helper_r:		; end of helper
			ld sp, (p_helper_rs)
			jp ntc_xn
p_nothing_c:		; call nothing (normal)
			ld (p_nothing_rs), sp
			ld sp, p_nothing
			jp ntc_xn
p_nothing_r:		; end of nothing
			ld sp, (p_nothing_rs)
			jp ntc_xn
p_getseven_c:		; call getseven (normal)
			ld hl, 0
			ld (var_getseven_getseven), hl
			ld (p_getseven_rs), sp
			ld sp, p_getseven
			jp ntc_xn
p_getseven_r:		; end of getseven
			ld sp, (p_getseven_rs)
			jp ntc_xn
p_sz_c:		; call sz (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_sz_n), de
			xor a
			ld (var_sz_sz), a
			ld (p_sz_rs), sp
			ld sp, p_sz
			jp ntc_xn
p_sz_r:		; end of sz
			ld sp, (p_sz_rs)
			jp ntc_xn
p_bumpshared_c:		; call bumpshared (normal)
			ld (p_bumpshared_rs), sp
			ld sp, p_bumpshared
			jp ntc_xn
p_bumpshared_r:		; end of bumpshared
			ld sp, (p_bumpshared_rs)
			jp ntc_xn
p_module2_helper_c:		; call helper (normal)
			ld hl, 0
			ld (var_module2_helper_helper), hl
			ld (p_module2_helper_rs), sp
			ld sp, p_module2_helper
			jp ntc_xn
p_module2_helper_r:		; end of helper
			ld sp, (p_module2_helper_rs)
			jp ntc_xn
p_mod2helper_c:		; call mod2helper (normal)
			ld hl, 0
			ld (var_mod2helper_mod2helper), hl
			ld (p_mod2helper_rs), sp
			ld sp, p_mod2helper
			jp ntc_xn
p_mod2helper_r:		; end of mod2helper
			ld sp, (p_mod2helper_rs)
			jp ntc_xn

